def is_king_neighbor(p1, p2):
    """Checks if two points are neighbors in the King's Graph."""
    x1, y1 = p1
    x2, y2 = p2
    return abs(x1 - x2) <= 1 and abs(y1 - y2) <= 1 and (x1 != x2 or y1 != y2)

def is_valid_is(S):
    """Checks if set S is an Independent Set."""
    points = list(S)
    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            if is_king_neighbor(points[i], points[j]):
                return False
    return True

# N=4 Counterexample Check
S_max = {(1, 1), (1, 3), (3, 1), (3, 3)}
S_A = {(1, 2), (3, 4)}
S_B = {(2, 1), (4, 3)}

print(f"S_A is valid: {is_valid_is(S_A)}")
print(f"S_B is valid: {is_valid_is(S_B)}")

# Check non-intersection with S_max
print(f"S_A intersects S_max: {bool(S_A.intersection(S_max))}")
print(f"S_B intersects S_max: {bool(S_B.intersection(S_max))}")
